UPDATE `oc_category_description` SET `description`='&lt;div class=&quot;ccp-cat-desc&quot;&gt;&lt;p class=&quot;ccp-cat-desc__lead&quot;&gt;Клиенты и вход: авторизация через соцсети, подтверждение телефона и локальное определение города по GeoIP.&lt;/p&gt;&lt;h3&gt;Что решают модули&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;Вход через социальные провайдеры&lt;/li&gt;&lt;li&gt;OTP-подтверждение номера телефона&lt;/li&gt;&lt;li&gt;Определение страны и города по GeoIP&lt;/li&gt;&lt;/ul&gt;&lt;p class=&quot;ccp-cat-desc__note&quot;&gt;Перед покупкой проверьте модуль в &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;тестовой админке&lt;/a&gt; (логин Demo, пароль Demo). Совместимость — OpenCart / ocStore 3.0.x, подробности указаны в карточке каждого модуля.&lt;/p&gt;&lt;/div&gt;', `meta_title`='Клиенты и авторизация для OpenCart и ocStore — CodeCart PRO', `meta_description`='Клиенты и авторизация: модули CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x. Описание, демо перед покупкой и цены.' WHERE `category_id`=76 AND `language_id`=3;
UPDATE `oc_category_description` SET `description`='&lt;div class=&quot;ccp-cat-desc&quot;&gt;&lt;p class=&quot;ccp-cat-desc__lead&quot;&gt;Інтеграції із зовнішніми системами: CRM-конектор для кількох магазинів, синхронізація з постачальниками та GeoIP.&lt;/p&gt;&lt;h3&gt;Що вирішують модулі&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;Read-only конектор магазинів до CRM&lt;/li&gt;&lt;li&gt;Синхронізація каталогу з постачальниками&lt;/li&gt;&lt;li&gt;Локальний GeoIP&lt;/li&gt;&lt;/ul&gt;&lt;p class=&quot;ccp-cat-desc__note&quot;&gt;Перед купівлею перевірте модуль у &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;тестовій адмінці&lt;/a&gt; (логін Demo, пароль Demo). Сумісність — OpenCart / ocStore 3.0.x, подробиці вказано в картці кожного модуля.&lt;/p&gt;&lt;/div&gt;', `meta_title`='Інтеграції та CRM для OpenCart та ocStore — CodeCart PRO', `meta_description`='Інтеграції та CRM: модулі CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x. Опис, демо перед купівлею та ціни.' WHERE `category_id`=77 AND `language_id`=1;
UPDATE `oc_category_description` SET `description`='&lt;div class=&quot;ccp-cat-desc&quot;&gt;&lt;p class=&quot;ccp-cat-desc__lead&quot;&gt;Integrations with external systems: a multi-store CRM connector, supplier synchronization and GeoIP.&lt;/p&gt;&lt;h3&gt;What these modules solve&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;Read-only store-to-CRM connector&lt;/li&gt;&lt;li&gt;Catalog synchronization with suppliers&lt;/li&gt;&lt;li&gt;Local GeoIP&lt;/li&gt;&lt;/ul&gt;&lt;p class=&quot;ccp-cat-desc__note&quot;&gt;Try a module in the &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;demo admin&lt;/a&gt; before buying (login Demo, password Demo). Compatibility: OpenCart / ocStore 3.0.x — see each module page for details.&lt;/p&gt;&lt;/div&gt;', `meta_title`='Integrations &amp; CRM for OpenCart and ocStore — CodeCart PRO', `meta_description`='Integrations &amp; CRM: CodeCart PRO modules for OpenCart 3.0.x and ocStore 3.0.x. Details, demo before purchase and pricing.' WHERE `category_id`=77 AND `language_id`=2;
