UPDATE `oc_category_description` SET `description`='&lt;div class=&quot;ccp-cat-desc&quot;&gt;&lt;p class=&quot;ccp-cat-desc__lead&quot;&gt;Інструменти розробника й адміністратора: аудит модулів до встановлення, очищення розширень, перевірка PHP і баз даних.&lt;/p&gt;&lt;h3&gt;Що вирішують модулі&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;Перевірка архівів модулів і сумісності з PHP 8&lt;/li&gt;&lt;li&gt;Безпечне очищення залишків розширень&lt;/li&gt;&lt;li&gt;Редактор перекладів та інструменти бази даних&lt;/li&gt;&lt;/ul&gt;&lt;p class=&quot;ccp-cat-desc__note&quot;&gt;Перед купівлею перевірте модуль у &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;тестовій адмінці&lt;/a&gt; (логін Demo, пароль Demo). Сумісність — OpenCart / ocStore 3.0.x, подробиці вказано в картці кожного модуля.&lt;/p&gt;&lt;/div&gt;', `meta_title`='Інструменти розробника та адміністратора для OpenCart та ocStore — CodeCart PRO', `meta_description`='Інструменти розробника та адміністратора: модулі CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x. Опис, демо перед купівлею та ціни.' WHERE `category_id`=78 AND `language_id`=1;
UPDATE `oc_category_description` SET `description`='&lt;div class=&quot;ccp-cat-desc&quot;&gt;&lt;p class=&quot;ccp-cat-desc__lead&quot;&gt;Developer and administrator tools: pre-install module audits, extension cleanup, PHP and database checks.&lt;/p&gt;&lt;h3&gt;What these modules solve&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;Module archive and PHP 8 compatibility checks&lt;/li&gt;&lt;li&gt;Safe cleanup of extension leftovers&lt;/li&gt;&lt;li&gt;Translation editor and database tools&lt;/li&gt;&lt;/ul&gt;&lt;p class=&quot;ccp-cat-desc__note&quot;&gt;Try a module in the &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;demo admin&lt;/a&gt; before buying (login Demo, password Demo). Compatibility: OpenCart / ocStore 3.0.x — see each module page for details.&lt;/p&gt;&lt;/div&gt;', `meta_title`='Developer &amp; Admin Tools for OpenCart and ocStore — CodeCart PRO', `meta_description`='Developer &amp; Admin Tools: CodeCart PRO modules for OpenCart 3.0.x and ocStore 3.0.x. Details, demo before purchase and pricing.' WHERE `category_id`=78 AND `language_id`=2;
